using System;using System.IO;using System.Linq;using System.Security.Cryptography;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.SceneManagement;using ParkingLotEnvironment.CloudPilot.Integrated;using ParkingLotEnvironment.Training;
namespace ParkingLotEnvironment.CloudPilot {public static class ContextRunner {
 const string Source="Assets/_Parkside/Scenes/ParklingLot.unity",W=ContextBuilder.W,Trial=W+"/ContextParkingLot.unity",Expected="f0b8c06d20310c564f4db024f3853099f20730ff79ff49ed5a4019ae82a23b27";
 static string output,trialHash;static GameObject root,preview;static Camera cam;static int frame=-1;static Vector3 pos;static Quaternion rot;static double started;
 static string Hash(string p){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
 static void Check(){if(File.Exists("/workspaces/parkside-setup/STOP")||Hash(Source)!=Expected)throw new Exception("STOP or source changed");}
 static void Args(){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"-collabOutput");output=Path.GetFullPath(a[i+1]);Directory.CreateDirectory(output);}
 public static void BuildBakeCapture(){try{Check();Args();if(File.Exists(Trial))throw new Exception("Candidate already exists");EditorSceneManager.OpenScene(Source);root=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name=="ParkingLot_CornerPilot_Root");ContextBuilder.Apply(root,output);ContextBuilder.Validate(root,output);foreach(var p in root.GetComponentsInChildren<ReflectionProbe>(true))p.enabled=false;var settings=UnityEngine.Object.Instantiate(Lightmapping.lightingSettings);settings.autoGenerate=false;AssetDatabase.CreateAsset(settings,W+"/ContextLighting.lighting");Lightmapping.lightingSettings=settings;AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());if(!EditorSceneManager.SaveScene(SceneManager.GetActiveScene(),Trial))throw new Exception("Candidate save failed");started=EditorApplication.timeSinceStartup;EditorApplication.update+=BakeTick;if(!Lightmapping.BakeAsync())throw new Exception("Bake rejected");}catch(Exception e){Fail(e);}}
 static void BakeTick(){try{Check();double elapsed=EditorApplication.timeSinceStartup-started;if(elapsed>1200){Lightmapping.Cancel();throw new Exception("Bake timeout");}if(elapsed<5||Lightmapping.isRunning)return;EditorApplication.update-=BakeTick;if(LightmapSettings.lightmaps.Length<1)throw new Exception("No lightmaps");int i=0;foreach(var p in root.GetComponentsInChildren<ReflectionProbe>(true)){p.enabled=true;p.boxProjection=true;p.resolution=512;p.mode=ReflectionProbeMode.Baked;p.timeSlicingMode=ReflectionProbeTimeSlicingMode.NoTimeSlicing;string path=W+"/ContextReflection_"+(i++)+".exr";if(!Lightmapping.BakeReflectionProbe(p,path))throw new Exception("Reflection bake failed");AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);p.mode=ReflectionProbeMode.Custom;p.customBakedTexture=AssetDatabase.LoadAssetAtPath<Texture>(path);EditorUtility.SetDirty(p);}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());if(!EditorSceneManager.SaveScene(SceneManager.GetActiveScene()))throw new Exception("Save failed");File.WriteAllText(output+"/bake-info.txt","Bake seconds="+elapsed+"; lightmaps="+LightmapSettings.lightmaps.Length+"; box reflection probes="+i+"; SHA="+Hash(Trial));BeginCapture();}catch(Exception e){Fail(e);}}
 public static void RefreshPorterAndCapture(){try{Check();Args();EditorSceneManager.OpenScene(Trial);root=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name=="ParkingLot_CornerPilot_Root");PorterMeshRefresh.Apply();VehiclePlateFinish.Apply(root);var quality=root.GetComponentInChildren<ParkingMapCameraQuality>();if(quality)UnityEngine.Object.DestroyImmediate(quality);var probe=root.GetComponentsInChildren<ReflectionProbe>(true).Single(p=>p.name=="LeftVehicles_LocalReflection");probe.mode=ReflectionProbeMode.Baked;probe.customBakedTexture=null;string reflection=W+"/ContextReflection_LeftFinal.exr";if(!Lightmapping.BakeReflectionProbe(probe,reflection))throw new Exception("Local reflection refresh failed");AssetDatabase.ImportAsset(reflection,ImportAssetOptions.ForceSynchronousImport);probe.mode=ReflectionProbeMode.Custom;probe.customBakedTexture=AssetDatabase.LoadAssetAtPath<Texture>(reflection);EditorUtility.SetDirty(probe);AssetDatabase.SaveAssets();ContextBuilder.Validate(root,output);EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());File.AppendAllText(output+"/context-changes.txt","Porter glazing split along exact polygon boundaries; printed chassis base replaced by steel rails; old floating plates disabled and 16 plates attached to eight cars. GI unaffected because Porter does not contribute to baked GI; left vehicle reflection recaptured.\n");File.AppendAllText(output+"/bake-info.txt","; Final corrected scene SHA="+Hash(Trial));frame=-1;BeginCapture();}catch(Exception e){Fail(e);}}
 public static void FinalGeometryBakeCapture(){try{Check();Args();EditorSceneManager.OpenScene(Trial);root=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name=="ParkingLot_CornerPilot_Root");PorterFinalBinding.Apply(root);var context=root.transform.Find("ParkingContext_ApprovedKitExtension");foreach(var r in context.GetComponentsInChildren<MeshRenderer>()){if(r.receiveGI==ReceiveGI.LightProbes){r.receiveGI=ReceiveGI.Lightmaps;r.scaleInLightmap=.18f;EditorUtility.SetDirty(r);}}foreach(var p in root.GetComponentsInChildren<ReflectionProbe>(true))p.enabled=false;AssetDatabase.SaveAssets();ContextBuilder.Validate(root,output);EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());started=EditorApplication.timeSinceStartup;EditorApplication.update+=FinalBakeTick;if(!Lightmapping.BakeAsync())throw new Exception("Final bake rejected");}catch(Exception e){Fail(e);}}
 static void FinalBakeTick(){try{Check();double elapsed=EditorApplication.timeSinceStartup-started;if(elapsed>1200){Lightmapping.Cancel();throw new Exception("Final bake timeout");}if(elapsed<5||Lightmapping.isRunning)return;EditorApplication.update-=FinalBakeTick;int i=0;foreach(var p in root.GetComponentsInChildren<ReflectionProbe>(true)){p.enabled=true;p.boxProjection=true;p.resolution=512;p.mode=ReflectionProbeMode.Baked;p.customBakedTexture=null;string path=W+"/FinalReflection_"+(i++)+".exr";if(!Lightmapping.BakeReflectionProbe(p,path))throw new Exception("Final probe bake failed");AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);p.mode=ReflectionProbeMode.Custom;p.customBakedTexture=AssetDatabase.LoadAssetAtPath<Texture>(path);EditorUtility.SetDirty(p);}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());File.WriteAllText(output+"/bake-info.txt","Final full bake seconds="+elapsed+"; lightmaps="+LightmapSettings.lightmaps.Length+"; three box probes; SHA="+Hash(Trial));File.AppendAllText(output+"/context-changes.txt","Final Porter STL winding repaired before material segmentation; fresh owned mesh assets explicitly rebound. Printed mounting base replaced by steel rails. New background buildings now receive baked GI, not unlit probe fallback.\n");frame=-1;BeginCapture();}catch(Exception e){Fail(e);}}
 public static void Capture(){try{Check();Args();BeginCapture();}catch(Exception e){Fail(e);}}
 static void BeginCapture(){trialHash=Hash(Trial);EditorSceneManager.OpenScene(Trial);root=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name=="ParkingLot_CornerPilot_Root");ContextBuilder.Validate(root,output);cam=root.GetComponentInChildren<Camera>();cam.enabled=false;pos=cam.transform.position;rot=cam.transform.rotation;EditorApplication.update+=CaptureTick;}
 static Quaternion Look(Vector3 from,Vector3 at){return Quaternion.LookRotation(at-from);}
 static void PreviewCar(){var layout=root.GetComponentInChildren<ParkingTrainingLayout>();var source=layout.transform.Find("Parked_P_Rear");preview=UnityEngine.Object.Instantiate(source.gameObject);preview.name="CaptureOnly_ChasePreview";preview.hideFlags=HideFlags.HideAndDontSave;foreach(var c in preview.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);var b=ContextBuilder.BoundsOf(preview);preview.transform.RotateAround(b.center,Vector3.up,180);b=ContextBuilder.BoundsOf(preview);preview.transform.position+=new Vector3(.7f-b.center.x,.005f-b.min.y,-11-b.center.z);foreach(var r in preview.GetComponentsInChildren<MeshRenderer>()){GameObjectUtility.SetStaticEditorFlags(r.gameObject,0);r.lightmapIndex=-1;r.receiveGI=ReceiveGI.LightProbes;}}
 static void CaptureTick(){try{Check();if(frame<0)Render(null,pos,rot,960,540);else if(frame==0){var p=new Vector3(-.3f,1.75f,-7.0f);Render("porter-close.png",p,Look(p,new Vector3(-5,1.0f,-4.5f)));}else if(frame==1){PreviewCar();var p=new Vector3(.7f,2.8f,-17.5f);Render("third-person.png",p,Look(p,new Vector3(.7f,1.2f,-6.7f)));UnityEngine.Object.DestroyImmediate(preview);preview=null;}else if(frame==2){var p=new Vector3(1,2.7f,-7);Render("turn-right.png",p,Look(p,new Vector3(14,1.9f,-9)));}else if(frame==3){var p=new Vector3(.7f,2.7f,-6);Render("turn-back.png",p,Look(p,new Vector3(.7f,1.8f,-27)));}else if(frame==4){var p=new Vector3(1,2.7f,-7);Render("turn-left.png",p,Look(p,new Vector3(-12,1.8f,-8)));}else if(frame==5)Render("eye.png",pos,rot);else if(frame==6){var p=new Vector3(-.1f,1.55f,-15.3f);Render("vehicles-close.png",p,Look(p,new Vector3(-5.1f,1.0f,-13.5f)));}else if(frame==7){var p=new Vector3(-.1f,1.65f,-9.7f);Render("sedan-close.png",p,Look(p,new Vector3(-5.2f,1.0f,-7.5f)));}else if(frame==8){var p=new Vector3(23,29,-35);Render("aerial.png",p,Look(p,new Vector3(0,1,-4)));}else if(frame==9){var p=new Vector3(.7f,3.6f,-33);Render("entrance.png",p,Look(p,new Vector3(.7f,2.1f,-20)));}else{EditorApplication.update-=CaptureTick;if(Hash(Trial)!=trialHash)throw new Exception("Candidate changed during capture");File.WriteAllText(output+"/capture-complete.txt","Reopened baked scene; 2 native 2560x1440 hero/Porter captures, 8 native 1920x1080 inspection captures; hero views also downsampled to 1080p. Chase vehicle is capture-only and is not saved or added to map obstacles. SHA="+trialHash);EditorApplication.Exit(0);return;}frame++;}catch(Exception e){Fail(e);}}
 static void Render(string name,Vector3 p,Quaternion q,int w=0,int h=0){if(w==0){bool hero=name=="third-person.png"||name=="porter-close.png";w=hero?2560:1920;h=hero?1440:1080;}var rt=new RenderTexture(w,h,24,RenderTextureFormat.ARGBHalf){antiAliasing=1,filterMode=FilterMode.Bilinear};var prev=RenderTexture.active;var target=cam.targetTexture;int aa=QualitySettings.antiAliasing;try{rt.Create();cam.targetTexture=rt;cam.transform.SetPositionAndRotation(p,q);cam.Render();if(name!=null){var native=new Texture2D(w,h,TextureFormat.RGB24,false);RenderTexture.active=rt;native.ReadPixels(new Rect(0,0,w,h),0,0);native.Apply();File.WriteAllBytes(output+"/"+name.Replace(".png",w==2560?"-1440p.png":"-1080p.png"),native.EncodeToPNG());UnityEngine.Object.DestroyImmediate(native);var small=new RenderTexture(1920,1080,0,RenderTextureFormat.ARGB32);small.Create();Graphics.Blit(rt,small);var pic=new Texture2D(1920,1080,TextureFormat.RGB24,false);RenderTexture.active=small;pic.ReadPixels(new Rect(0,0,1920,1080),0,0);pic.Apply();File.WriteAllBytes(output+"/"+name,pic.EncodeToPNG());UnityEngine.Object.DestroyImmediate(pic);RenderTexture.active=rt;small.Release();UnityEngine.Object.DestroyImmediate(small);}}finally{cam.targetTexture=target;RenderTexture.active=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);if(QualitySettings.antiAliasing!=aa)throw new Exception("Camera did not restore quality state");}}
 static void Fail(Exception e){EditorApplication.update-=BakeTick;EditorApplication.update-=FinalBakeTick;EditorApplication.update-=CaptureTick;if(preview)UnityEngine.Object.DestroyImmediate(preview);Debug.LogException(e);if(output!=null)File.WriteAllText(output+"/FAILED.txt",e.ToString());EditorApplication.Exit(1);}
